using ClinicHub.Domain.Common;

namespace ClinicHub.Domain.Attachments;

/// <summary>
/// One stored file's metadata (docs/design/attachments.md § 4). A clinic's file, or a platform file when
/// <see cref="ClinicId"/> is null. All access goes through <c>IAttachmentService</c>. The row is never removed: delete and
/// replace set <see cref="DeletedAt"/>, and the file stays on disk.
/// </summary>
public class Attachment : IClinicOrShared, IHasTimestamps
{
    /// <summary>Generated by the service, not sequential: it names the file on disk.</summary>
    public Guid Id { get; set; }
    /// <summary>Null = a platform file. Stamped by the save interceptor.</summary>
    public int? ClinicId { get; set; }
    public string Module { get; set; }
    /// <summary>The owning record's key as text, so any key type fits. No database link: it can be in any table.</summary>
    public string RefId { get; set; }
    /// <summary>The user's file name. For display and download only: never used in a path, never logged.</summary>
    public string OriginalFileName { get; set; }
    /// <summary>The checked type (<c>png</c>, <c>xlsx</c>…).</summary>
    public string TypeKey { get; set; }
    public long SizeBytes { get; set; }
    /// <summary><c>clinics/&lt;clinicId&gt;/&lt;Id&gt;</c> or <c>platform/&lt;Id&gt;</c>, stored so reads never build a path from a request.</summary>
    public string StorageKey { get; set; }
    /// <summary>A user ID, because a super admin has no staff row.</summary>
    public int CreatedByUserId { get; set; }
    public DateTime? DeletedAt { get; set; }
    public int? DeletedByUserId { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime UpdatedAt { get; set; }
}
